entries[454426] = { ["name"] = "Delivered Doom", ["text"] = "Damage dealt when your Fatebound Coin flips tails is increased by 30% if there are no other enemies near the target.\n\nEach additional nearby enemy reduces this bonus by 6%." }
entries[454428] = { ["name"] = "Fateful Ending", ["text"] = "When your Fatebound Coin flips the same face for the seventh time in a row, keep the lucky coin to gain 7% Agility until you leave combat for 10 seconds. If you already have a lucky coin, it instead deals (420% of Attack Power) Cosmic damage to your target." }
entries[454429] = { ["name"] = "Fate Intertwined", ["text"] = "Outlaw\nFate Intertwined duplicates 30% of Dispatch critical strike damage as Cosmic to 2 additional nearby enemies. If there are no additional nearby targets, duplicate 30% to the primary target instead.\n\nAssassination\nFate Intertwined duplicates 30% of Envenom critical strike damage as Cosmic to 2 additional nearby enemies. If there are no additional nearby targets, duplicate 30% to the primary target instead." }
entries[454430] = { ["name"] = "Double Jeopardy", ["text"] = "Your first Fatebound Coin flip after breaking Stealth flips two coins that are guaranteed to match the same outcome." }
entries[454431] = { ["name"] = "The Severed Satchel", ["text"] = "2 sec cast 2\nReagents:\nAdorning Ribbon (2), Duskweave Bolt (5), Dawnweave Bolt (5)\nOptional Reagents:\nEmbroidery Thread (#333)\nSpecialization:\nQuality Fabric (25)\n\nThe Severed Satchel\nBinds when picked up\nUnique\n36 Slot Bag\nEquip: Increases the maximum yield of Khaz Algar Unraveling by 1.\n\n[ Equip effect requires Khaz Algar Tailoring 1 ][ Equip effect requires Khaz Algar Tailoring 1 ]68\n\"A container spun from The Weaver's master artisans, capable of maximizing the value of cloth as elusive as Dawnweave and Duskweave.\"" }
entries[454432] = { ["name"] = "Inexorable March", ["text"] = "You cannot be slowed below 70% of normal movement speed while your Fatebound Coin flips have an active streak of at least 2 flips matching the same face." }
entries[454433] = { ["name"] = "Death's Arrival", ["text"] = "Outlaw\nGrappling Hook may be used a second time within 3 sec with no cooldown, but its total cooldown is increased by 5 sec.\n\nAssassination\nShadowstep may be used a second time within 3 sec with no cooldown, but its total cooldown is increased by 5 sec." }
entries[454434] = { ["name"] = "Inevitable End", ["text"] = "Outlaw\nCold Blood now benefits the next two abilities but only applies to Dispatch. Fatebound Coins flipped by these abilities are guaranteed to match the same outcome as the last flip.\n\nAssassination\nCold Blood now benefits the next two abilities but only applies to Envenom. Fatebound Coins flipped by these abilities are guaranteed to match the same outcome as the last flip." }
entries[454435] = { ["name"] = "Destiny Defined", ["text"] = "Outlaw\nSinister Strike has 5% increased chance to strike an additional time and your Fatebound Coins flipped have an additional 5% chance to match the same face as the last flip.\n\nAssassination\nWeapon poisons have 5% increased application chance and your Fatebound Coins flipped have an additional 5% chance to match the same face as the last flip." }
