entries[454441] = { ["name"] = "Becoming an Algari Angler", ["text"] = "5 yd range\n3.2 sec cast\nBecoming an Angler is easy!\n\nCast your line and reel in the many secrets Khaz Algar has to offer.\n\nCaught Fish and Fishing Pools will appear here in your trusty Fishing Journal. The records here will detail these fanciful fish and give indication on where you might find them!\nProfession:\nFishing (1)" }
entries[454442] = { ["name"] = "Fishing Skill and You", ["text"] = "5 yd range\n3.2 sec cast\nAs your ability to reel in the perfect catch improves, so does your Fishing Skill!\n\nImproving your Fishing Skill to the best of your ability is the difference between catching an old boot, or a prized trophy fish.\nProfession:\nFishing (25)" }
entries[454443] = { ["name"] = "Quiet River Bass", ["text"] = "Instant\nShimmering emerald scales coat this otherwise unassuming fish. Both plentiful and appetizing, the Quiet River Bass is a staple in any seafood dish.\n\nSpecial:\n\nFresh Fillet\n\nSalvaging this fish with the Cooking skill can produce a moderate amount of Fresh Fillet.\n\nAreas you can find this fish:\n\n- Isle of Dorn\n- The Ringing Deeps\n- Siren Isle\n\nFishing Pools:\n\n- Calm Surfacing Ripple\n- River Bass Pool\nProfession:\nFishing" }
